  FT["PH-H797"] = {"id":"PH-H797","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1953/ra_957_1953.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将八打雁省 Talisay市镇 Balas村 Buco小村改设为村的法案","en":"An Act to Convert the Sitio of Buco in the Barrio of Balas, Municipality of Talisay, Province of Batangas, Into a Barrio","orig":"An Act to Convert the Sitio of Buco in the Barrio of Balas, Municipality of Talisay, Province of Batangas, Into a Barrio"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 957","issuingBody":"Congress of the Philippines","promulgatedDate":"1953-06-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1953/ra_957_1953.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H797-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Buco in the barrio of Balas, municipality of Talisay, Province of Batangas, is hereby separated from said barrio and converted into a new barrio to be known as the barrio of Buco."}},{"id":"PH-H797-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 20, 1953."}}],"pack":"ph-p11","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Convert the Sitio of Buco in the Barrio of Balas, Municipality of Talisay, Province of Batangas, Into a Barrio","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
